k=0; P=re.compile(r'en Puerto Rico, por ejemplo,.*?por lo que conviene confirmarlo con un CPA',re.S)
for f in sorted(glob.glob('work/GREEN-L5-es-ES/*.txt')):
    s=open(f,encoding='utf-8').read()
    def rep(m):
        global k; r=S[k]; k+=1; return r
    s=P.sub(rep,s)
    s=s.replace('un CPA','un asesor fiscal').replace('CPA','asesor fiscal').replace('Puerto Rico','España')
    open(f,'w',encoding='utf-8').write(s)
